import os
from typing import Any, Dict, Optional
from urllib.parse import urlencode, urljoin

import requests


class IBMAppIDOAuthClient:
    def __init__(
        self,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        issuer: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        session: Optional[requests.Session] = None,
    ) -> None:
        self.client_id = client_id or os.getenv("IBM_APPID_CLIENT_ID")
        self.client_secret = client_secret or os.getenv("IBM_APPID_CLIENT_SECRET")
        self.issuer = issuer or os.getenv("IBM_APPID_ISSUER")
        self.redirect_uri = redirect_uri or os.getenv("IBM_APPID_REDIRECT_URI")
        self.session = session or requests.Session()

        if not self.client_id:
            raise ValueError("Missing IBM_APPID_CLIENT_ID")
        if not self.client_secret:
            raise ValueError("Missing IBM_APPID_CLIENT_SECRET")
        if not self.issuer:
            raise ValueError("Missing IBM_APPID_ISSUER")
        if not self.redirect_uri:
            raise ValueError("Missing IBM_APPID_REDIRECT_URI")

        self.issuer = self.issuer.rstrip("/") + "/"

    @property
    def authorize_endpoint(self) -> str:
        return urljoin(self.issuer, "authorize")

    @property
    def token_endpoint(self) -> str:
        return urljoin(self.issuer, "token")

    @property
    def userinfo_endpoint(self) -> str:
        return urljoin(self.issuer, "userinfo")

    def build_authorize_url(
        self,
        state: str,
        scope: str = "openid profile email",
        response_type: str = "code",
        nonce: Optional[str] = None,
        prompt: Optional[str] = None,
    ) -> str:
        params: Dict[str, Any] = {
            "response_type": response_type,
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": scope,
            "state": state,
        }
        if nonce:
            params["nonce"] = nonce
        if prompt:
            params["prompt"] = prompt
        return f"{self.authorize_endpoint}?{urlencode(params)}"

    def exchange_code_for_tokens(
        self,
        code: str,
        code_verifier: Optional[str] = None,
    ) -> Dict[str, Any]:
        data: Dict[str, Any] = {
            "grant_type": "authorization_code",
            "code": code,
            "redirect_uri": self.redirect_uri,
            "client_id": self.client_id,
            "client_secret": self.client_secret,
        }
        if code_verifier:
            data["code_verifier"] = code_verifier

        resp = self.session.post(
            self.token_endpoint,
            data=data,
            headers={"Accept": "application/json"},
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        resp = self.session.get(
            self.userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json"},
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()


def handle_oauth_callback(query_params: Dict[str, Any]) -> Dict[str, Any]:
    """
    Handles an OAuth/OIDC callback by exchanging the authorization code for tokens.
    Expects query_params to include:
      - code
      - state
    Optional:
      - code_verifier
    """
    error = query_params.get("error")
    if error:
        raise ValueError(f"OAuth callback error: {error}")

    code = query_params.get("code")
    if not code:
        raise ValueError("Missing authorization code")

    client = IBMAppIDOAuthClient()
    tokens = client.exchange_code_for_tokens(
        code=code,
        code_verifier=query_params.get("code_verifier"),
    )

    result: Dict[str, Any] = {"tokens": tokens}
    access_token = tokens.get("access_token")
    if access_token:
        try:
            result["userinfo"] = client.fetch_userinfo(access_token)
        except requests.RequestException:
            pass

    return result
